package org.springframework.samples.petclinic.mapper;

import org.jspecify.annotations.NonNull;
import org.mapstruct.Mapper;
import org.mapstruct.Mapping;
import org.springframework.data.domain.Page;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerDto;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;

import java.util.Collection;
import java.util.List;
import java.util.Map;

/**
 * Maps Owner & OwnerDto using Mapstruct
 */
@Mapper(uses = PetMapper.class)
public interface OwnerMapper {

    Map<String, String> CITY_REGIONS = Map.of(
        "Sydney", "NSW",
        "Melbourne", "VIC",
        "Brisbane", "QLD");

    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
    @Mapping(target = "initials", expression = "java(toInitials(owner))")
    @Mapping(target = "membershipNumber", expression = "java(toMembershipNumber(owner))")
    @Mapping(target = "membershipTier", expression = "java(toMembershipTier(owner))")
    @Mapping(target = "locality", expression = "java(toLocality(owner))")
    @Mapping(target = "bulkSignupWarning", expression = "java(Boolean.TRUE.equals(owner.getBulkSignupWarning()))")
    @Mapping(target = "sharesHousehold", ignore = true)
    OwnerDto toOwnerDto(Owner owner);

    /**
     * The region of the owner's city from {@link #CITY_REGIONS}, or 'UNKNOWN' when the city is not listed.
     */
    default String toLocality(Owner owner) {
        return owner.getCity() == null ? "UNKNOWN" : CITY_REGIONS.getOrDefault(owner.getCity(), "UNKNOWN");
    }

    /**
     * 'SILVER' when the owner has no namesakes and an email is present, otherwise 'BRONZE'.
     */
    default String toMembershipTier(Owner owner) {
        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
        return hasEmail && noNamesakes ? "SILVER" : "BRONZE";
    }

    /**
     * Builds the membership number '&lt;customerCode&gt;-M&lt;YY&gt;', where YY is the last two digits of
     * the registration date's year.
     */
    default String toMembershipNumber(Owner owner) {
        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
            return null;
        }
        return String.format("%s-M%02d", owner.getCustomerCode(),
            Math.floorMod(owner.getRegistrationDate().getYear(), 100));
    }

    default String toInitials(Owner owner) {
        return initial(owner.getFirstName()) + initial(owner.getLastName());
    }

    private static String initial(String name) {
        return name == null || name.isEmpty() ? "" : Character.toUpperCase(name.charAt(0)) + ".";
    }

    Owner toOwner(OwnerDto ownerDto);

    @Mapping(target = "id", ignore = true)
    @Mapping(target = "pets", ignore = true)
    @Mapping(target = "customerCode", ignore = true)
    @Mapping(target = "householdId", ignore = true)
    @Mapping(target = "namesakeCount", ignore = true)
    @Mapping(target = "bulkSignupWarning", ignore = true)
    Owner toOwner(OwnerFieldsDto ownerDto);

    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);

    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);

    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
        OwnerPageDto ownerPageDto = new OwnerPageDto();
        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
        ownerPageDto.setPage(ownerPage.getNumber());
        ownerPageDto.setSize(ownerPage.getSize());
        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
        return ownerPageDto;
    }
}
package org.springframework.samples.petclinic.acceptance;

import org.junit.jupiter.api.Test;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import tools.jackson.databind.node.ObjectNode;

/** tier-gold: membershipTier is 'GOLD' when the owner's household has 3+ members after this
 * create. Build a shared household (same lastName + address, sharesHousehold) and assert the third
 * member is GOLD. */
class AcceptanceTest extends AcceptanceBase {

	@Test
	void coreGoldForThreeMemberHousehold() throws Exception {
		String lastName = uniqueLastName();
		String address = uniqueAddress();
		for (int i = 0; i < 2; i++) {
			ObjectNode m = ownerNode();
			m.put("lastName", lastName);
			m.put("address", address);
			m.put("sharesHousehold", true);
			createOwnerOk(m);
		}
		ObjectNode third = ownerNode();
		third.put("lastName", lastName);
		third.put("address", address);
		third.put("sharesHousehold", true);
		int id = createOwnerOk(third);
		getOwner(id).andExpect(jsonPath("$.membershipTier").value("GOLD"));
	}
}
        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
        List<String> missingFields = RequiredOwnerFields.missingFields(ownerFieldsDto);
        if (!missingFields.isEmpty()) {
            throw new MissingRequiredFieldsException(missingFields);
        }
        HttpHeaders headers = new HttpHeaders();
        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
        String telephone = OwnerTelephone.normalize(ownerFieldsDto.getTelephone());
        if (this.clinicService.ownerTelephoneExists(telephone)) {
            throw new DuplicateTelephoneException(telephone);
        }
        String address = AddressNormalizer.normalize(ownerFieldsDto.getAddress());
        owner.setAddress(address);
        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
        if (!sharesHousehold
            && this.clinicService.ownerHouseholdExists(ownerFieldsDto.getLastName(), address)) {
            throw new DuplicateHouseholdException(ownerFieldsDto.getLastName(), address);
        }
        if (this.clinicService.countOwnersInCity(ownerFieldsDto.getCity()) >= CITY_CAPACITY) {
            throw new CityCapacityExceededException(ownerFieldsDto.getCity(), CITY_CAPACITY);
        }
        LocalDate registrationDate = BusinessDays.rollForward(
            owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now());
        long ownersCreatedToday = this.clinicService.countOwnersRegisteredOn(registrationDate);
        if (ownersCreatedToday >= DAILY_OWNER_LIMIT) {
            throw new DailyOwnerLimitExceededException(DAILY_OWNER_LIMIT);
        }
        if (sharesHousehold) {
            this.clinicService.joinHousehold(owner);
        }
        owner.setTelephone(telephone);
        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
        owner.setRegistrationDate(registrationDate);
        owner.setBulkSignupWarning(ownersCreatedToday > BULK_SIGNUP_THRESHOLD);
        this.clinicService.saveOwner(owner);
        AUDIT.info("Owner created: id={}, customerCode={}, registrationDate={}",
            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
        headers.setLocation(UriComponentsBuilder.newInstance()
            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
        if (currentOwner == null) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        String telephone = OwnerTelephone.normalize(ownerFieldsDto.getTelephone());
            owner.setCustomerCode(customerCode(owner.getCity(), owner.getLastName(),
                ownerRepository.countByCityIgnoringCase(lowerCase(owner.getCity())) + 1));
            owner.setNamesakeCount((int) ownerRepository.countByFirstNameAndLastNameIgnoringCase(
                lowerCase(owner.getFirstName()), lowerCase(owner.getLastName())));
        }
        ownerRepository.save(owner);

    }

    @Override
    @Transactional(readOnly = true)
    public boolean ownerTelephoneExists(String telephone) throws DataAccessException {
        return ownerRepository.existsByTelephone(telephone);
    }

    @Override
    @Transactional(readOnly = true)
    public boolean ownerHouseholdExists(String lastName, String address) throws DataAccessException {
        return !findHouseholdMembers(lastName, address).isEmpty();
    }

    @Override
    @Transactional(readOnly = true)
    public long countOwnersInCity(String city) throws DataAccessException {
        return ownerRepository.countByCityIgnoringCase(lowerCase(city));
    }

    @Override
    @Transactional(readOnly = true)
    public long countOwnersRegisteredOn(LocalDate registrationDate) throws DataAccessException {
        return ownerRepository.countByRegistrationDate(registrationDate);
    }

    @Override
    @Transactional
    public void joinHousehold(Owner owner) throws DataAccessException {
        List<Owner> members = findHouseholdMembers(owner.getLastName(), owner.getAddress());
        if (members.isEmpty()) {
            return;
        }
        String householdId = members.stream()
            .map(Owner::getHouseholdId)
            .filter(id -> id != null && !id.isBlank())
            .findFirst()
            .orElseGet(() -> UUID.randomUUID().toString());
        for (Owner member : members) {
            if (!householdId.equals(member.getHouseholdId())) {
                member.setHouseholdId(householdId);
                ownerRepository.save(member);
            }
        }
        owner.setHouseholdId(householdId);
    }

    /**
     * Finds the owners with the same last name (ignoring case and runs of whitespace) and the same
     * normalized address.
     */
    private List<Owner> findHouseholdMembers(String lastName, String address) {
        String normalizedAddress = AddressNormalizer.normalize(address);
        return ownerRepository.findByLastNameIgnoringCase(normalizeForComparison(lastName)).stream()
            .filter(existing -> AddressNormalizer.normalize(existing.getAddress()).equals(normalizedAddress))
            .toList();
    }

    /** Trims the value, collapses runs of whitespace into a single space and lower-cases it. */
    private static String normalizeForComparison(String value) {
        return value == null ? "" : value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }

    private static String lowerCase(String value) {
        return value == null ? null : value.toLowerCase(Locale.ROOT);
    }

    @Override
    @Transactional(readOnly = true)
    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
        return ownerRepository.findByLastName(lastName);
    }

    @Override
